    while i >= 0 and w[i] in TERM:
        i -= 1
    return True

def _next_upper(nw):
    if not nw:
        return False
    c = nw[0]
    return c.isupper() or c.isdigit() or c in OPENER

def split_sentences(text: str) -> List[str]:
